use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut cur: int = self.root
        let mut found = false
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                found = true
                cur = -1
            } else if x < k {
                cur = self.lefts[cur]
            } else {
                cur = self.rights[cur]
            }
        }
        found
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) {
            return false
        }
        let idx: int = self.keys.len()
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root == -1 {
            self.root = idx
            return true
        }
        let mut cur: int = self.root
        let mut done = false
        while !done {
            if x < self.keys[cur] {
                if self.lefts[cur] == -1 {
                    self.lefts[cur] = idx
                    done = true
                } else {
                    cur = self.lefts[cur]
                }
            } else {
                if self.rights[cur] == -1 {
                    self.rights[cur] = idx
                    done = true
                } else {
                    cur = self.rights[cur]
                }
            }
        }
        true
    }

    fn delete(self, x: int) -> bool {
        let mut cur: int = self.root
        let mut parent: int = -1
        let mut is_left = false
        while cur != -1 && self.keys[cur] != x {
            parent = cur
            if x < self.keys[cur] {
                is_left = true
                cur = self.lefts[cur]
            } else {
                is_left = false
                cur = self.rights[cur]
            }
        }
        if cur == -1 {
            return false
        }
        if self.lefts[cur] == -1 || self.rights[cur] == -1 {
            let mut child: int = self.lefts[cur]
            if child == -1 {
                child = self.rights[cur]
            }
            if parent == -1 {
                self.root = child
            } else if is_left {
                self.lefts[parent] = child
            } else {
                self.rights[parent] = child
            }
        } else {
            let mut sp: int = cur
            let mut s: int = self.rights[cur]
            while self.lefts[s] != -1 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[cur] = self.keys[s]
            if sp == cur {
                self.rights[cur] = self.rights[s]
            } else {
                self.lefts[sp] = self.rights[s]
            }
        }
        true
    }

    fn height_of(self, n: int) -> int {
        if n == -1 {
            return 0
        }
        let a = self.height_of(self.lefts[n])
        let b = self.height_of(self.rights[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn collect_in(self, n: int, out: Vec<int>) -> Vec<int> {
        let mut res = out
        if n == -1 {
            return res
        }
        res = self.collect_in(self.lefts[n], res)
        res.push(self.keys[n])
        self.collect_in(self.rights[n], res)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse::<int>().unwrap_or(0)
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            let items: Vec<int> = t.collect_in(t.root, [])
            if items.len() == 0 {
                println("<empty>")
            } else {
                let strs: Vec<string> = items.map(|v| "${v}").collect()
                println(strs.join(" "))
            }
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c: int = t.root
                while t.lefts[c] != -1 {
                    c = t.lefts[c]
                }
                println("${t.keys[c]}")
            }
        } else if cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c: int = t.root
                while t.rights[c] != -1 {
                    c = t.rights[c]
                }
                println("${t.keys[c]}")
            }
        }
    }
}

